import { readInvoice } from './invoice_repository';
const sessions = new Map<string, string>([
  ['session-a', 'tenant-a'],
  ['session-b', 'tenant-b'],
]);
export function handleGetInvoice(request: { sessionId: string; invoiceId: string }): string | null {
  const tenantId = sessions.get(request.sessionId);
  if (tenantId === undefined) return null;
  return readInvoice(tenantId, request.invoiceId);
}

