import { invoices } from './invoice_data';

export function readInvoice(tenantId: string, invoiceId: string): string | null {
  const invoice = invoices.find(row => row.id === invoiceId && row.tenantId === tenantId);
  return invoice?.billingDetails ?? null;
}

